const LESSONS_11 = {
    'quimica/Equilíbrio químico — conceito e Kc': {
        title: 'Equilíbrio químico e constante Kc',
        body: `**1. Reacção reversível e equilíbrio**\nNuma reacção reversível aA + bB ⇌ cC + dD, atingido o equilíbrio:\n• as concentrações deixam de variar (equilíbrio DINÂMICO)\n• velocidade directa = velocidade inversa\n• a reacção continua a ocorrer nos dois sentidos à mesma taxa\n\n**2. Constante de equilíbrio Kc**\n   **Kc = [C]ᶜ · [D]ᵈ / ([A]ᵃ · [B]ᵇ)**\n(concentrações em mol/dm³, em EQUILÍBRIO)\n\n**3. Regras importantes**\n• Sólidos puros e líquidos puros NÃO entram na expressão.\n• Kc depende APENAS da temperatura.\n• Kc grande (>>1) → equilíbrio favorece produtos.\n• Kc pequeno (<<1) → equilíbrio favorece reagentes.\n• Reacção inversa: Kc' = 1/Kc.\n• Equação multiplicada por n: novo Kc = (Kc original)ⁿ.\n• Soma de equações: multiplicar Kc.\n\n**4. Exemplo numérico**\nN₂(g) + 3 H₂(g) ⇌ 2 NH₃(g) num reactor de 2,0 dm³:\nNo equilíbrio: 0,40 mol N₂; 1,20 mol H₂; 0,80 mol NH₃.\nConcentrações: [N₂]=0,20; [H₂]=0,60; [NH₃]=0,40.\nKc = (0,40)² / (0,20 · 0,60³) = 0,16 / 0,0432 ≈ 3,7.\n\n**❌ ERROS FREQUENTES EM EXAME**\n• Incluir sólidos ou H₂O líquida na expressão de Kc — NÃO entram.\n• Esquecer os EXPOENTES (coeficientes estequiométricos).\n• Trocar produtos por reagentes — Kc tem produtos no NUMERADOR.\n• Usar moles em vez de concentrações (mol/dm³).\n• Achar que Kc muda com a concentração ou catalisador — só com T.\n• Dar valor de Kc com unidades — Kc é adimensional (definição IUPAC moderna).`
    },
    'quimica/Quociente de reacção e princípio de Le Châtelier': {
        title: 'Quociente Qc e princípio de Le Châtelier',
        body: `**1. Quociente de reacção Qc**\nTem a MESMA forma de Kc mas com concentrações em QUALQUER instante (não necessariamente equilíbrio).\n\n**2. Comparação Qc vs Kc**\n• Qc < Kc → reacção evolui no sentido DIRECTO (forma mais produtos)\n• Qc > Kc → reacção evolui no sentido INVERSO (forma mais reagentes)\n• Qc = Kc → sistema em EQUILÍBRIO\n\nMnemónica: o sistema evolui sempre para "Q chegar a K".\n\n**3. Princípio de Le Châtelier**\n"Quando uma perturbação é imposta a um sistema em equilíbrio, o sistema evolui no sentido que CONTRARIA essa perturbação."\n\n**4. Efeitos das perturbações**\n• ↑ [reagente] → desloca para PRODUTOS (consome o excesso)\n• ↑ [produto] → desloca para REAGENTES\n• Remover produto → desloca para PRODUTOS\n\n**Temperatura**:\n• EXOTÉRMICA (ΔH<0, calor é "produto"): ↑T → desloca para REAGENTES; Kc DIMINUI\n• ENDOTÉRMICA (ΔH>0, calor é "reagente"): ↑T → desloca para PRODUTOS; Kc AUMENTA\n\n**Pressão (gases)**:\n• ↑P (↓V) → desloca para o lado com MENOS moles GASOSAS\n• ↓P (↑V) → desloca para o lado com MAIS moles gasosas\n• Se Δnᵍ = 0 → P NÃO desloca o equilíbrio\n\n**Catalisador**: acelera AMBOS os sentidos por igual → NÃO desloca o equilíbrio, NÃO altera Kc. Só faz chegar mais depressa ao equilíbrio.\n\n**Adição de gás inerte (a V constante)**: NÃO altera as pressões parciais → NÃO desloca o equilíbrio.\n\n**❌ ERROS FREQUENTES EM EXAME**\n• Achar que catalisador desloca o equilíbrio — NÃO desloca.\n• Confundir sentido directo com inverso quando Qc < Kc (sistema vai PARA produtos).\n• Aplicar regra da pressão quando Δnᵍ = 0 (ex: H₂ + I₂ ⇌ 2 HI) — não há efeito.\n• Inverter o efeito da temperatura (exo/endo).\n• Esquecer que apenas a TEMPERATURA altera o valor de Kc.\n• Pensar que adicionar gás inerte a V constante desloca — não desloca.`
    },
    'quimica/Equilíbrio ácido-base — pH e Kw': {
        title: 'Equilíbrio ácido-base — pH, pOH e Kw',
        body: `**1. Brønsted-Lowry (1923)**\n• **Ácido**: cede um protão (H⁺).\n• **Base**: recebe um protão.\n• **Par conjugado**: HA + B ⇌ A⁻ + HB⁺.\n• **Anfotérica** (anfiprótica): pode actuar como ácido OU base. Ex: H₂O, HCO₃⁻, HS⁻, H₂PO₄⁻.\n\n**2. Autoionização da água**\n   2 H₂O(ℓ) ⇌ H₃O⁺(aq) + OH⁻(aq)\nA água é simultaneamente o ácido e a base do seu equilíbrio.\n\n**3. Produto iónico da água, Kw**\n   **Kw = [H₃O⁺] · [OH⁻]**\n• A 25 °C: Kw = 1,0 × 10⁻¹⁴ → [H₃O⁺] = [OH⁻] = 1,0 × 10⁻⁷ mol/dm³.\n• Kw depende APENAS da temperatura. Como a autoionização é endotérmica, Kw aumenta com T:\n   — 0 °C ≈ 1,1 × 10⁻¹⁵\n   — 25 °C = 1,0 × 10⁻¹⁴\n   — 50 °C ≈ 5,5 × 10⁻¹⁴\n   — 100 °C ≈ 5,1 × 10⁻¹³\n\n**4. Escala de Sørensen — pH e pOH**\n   pH = −log[H₃O⁺]    pOH = −log[OH⁻]\n   pH + pOH = pKw    (= 14 a 25 °C)\nReversamente: [H₃O⁺] = 10⁻ᵖᴴ.\n\n**5. Classificação (a 25 °C)**\n• pH < 7 → ácida\n• pH = 7 → neutra\n• pH > 7 → básica\n\n**6. Diluição**\n• Diluir ácido → pH sobe (aproxima-se de 7).\n• Diluir base → pH desce (aproxima-se de 7).\n• Por simples diluição, nunca se cruza o valor neutro.\n\n**7. Indicadores ácido-base**\n• Tornesol: vermelho (<5) → azul (>8)\n• Fenolftaleína: incolor (<8,3) → carmim (>10)\n• Azul de bromotimol: amarelo (<6) → azul (>7,6)\n• Alaranjado de metilo: vermelho (<3,1) → amarelo (>4,4)\n\n**❌ ERROS FREQUENTES EM EXAME**\n• Confundir "neutro" com "pH = 7" → SÓ é verdade a 25 °C. Em água pura a 50 °C o pH neutro é ≈ 6,6 (continua neutra porque [H₃O⁺] = [OH⁻]).\n• Esquecer o factor 10 entre unidades de pH: ΔpH = 1 → 10× a [H₃O⁺]. Solução de pH 3 tem 100× mais H₃O⁺ que pH 5.\n• Achar que diluir um ácido pode "passar" para pH > 7 → IMPOSSÍVEL por diluição em água.\n• Pensar que Kw é constante universal → muda com T.`
    },
    'quimica/Ácidos e bases fortes e fracos — Ka e Kb': {
        title: 'Ka, Kb e força de ácidos e bases',
        body: `**1. "Força" = extensão da ionização**\n• **Forte**: ioniza-se quase totalmente (>99%).\n• **Fraco**: ioniza-se parcialmente, em equilíbrio.\nNÃO confundir com concentração! Um ácido pode ser FORTE e DILUÍDO ou FRACO e CONCENTRADO.\n\n**2. Ácidos fortes — memorizar**\nHCl · HBr · HI · HNO₃ · H₂SO₄ (1.ª ioniz.) · HClO₄.\nReacção COMPLETA → para HA de concentração C:\n   [H₃O⁺] ≈ C  →  **pH = −log C**\nEx: HCl 0,01 mol/dm³ → pH = 2.\n\n**3. Bases fortes**\nNaOH · KOH · LiOH · Ca(OH)₂ · Ba(OH)₂.\n   [OH⁻] ≈ C  →  pOH = −log C  →  pH = 14 − pOH (a 25 °C)\n\n**4. Ácidos fracos — Ka**\n   HA + H₂O ⇌ A⁻ + H₃O⁺\n   **Ka = [A⁻]·[H₃O⁺] / [HA]**\n\nValores típicos a 25 °C:\n• HF → 6,8 × 10⁻⁴ (pKa 3,2)\n• CH₃COOH → 1,8 × 10⁻⁵ (pKa 4,7)\n• H₂CO₃ (1.ª) → 4,3 × 10⁻⁷ (pKa 6,4)\n• NH₄⁺ → 5,6 × 10⁻¹⁰ (pKa 9,2)\n• HCN → 6,2 × 10⁻¹⁰ (pKa 9,2)\n\n**Cálculo do pH** (com Ka << C, aproximação x pequeno):\n   **[H₃O⁺] = √(Ka · C)**    →    pH = ½(pKa − log C)\nEx: ácido acético 0,10 mol/dm³ → [H₃O⁺] = √(1,8×10⁻⁵ · 0,10) ≈ 1,3×10⁻³ → pH ≈ 2,9.\n\n**5. Bases fracas — Kb**\n   B + H₂O ⇌ BH⁺ + OH⁻\n   **Kb = [BH⁺]·[OH⁻] / [B]**\nEx: NH₃ → Kb = 1,8 × 10⁻⁵; CH₃COO⁻ → Kb = 5,6 × 10⁻¹⁰.\n\n**6. Relação fundamental: Ka · Kb = Kw**\nPara qualquer par ácido-base CONJUGADO, à mesma T:\n   **Ka(HA) × Kb(A⁻) = Kw**    ⇔    **pKa + pKb = 14** (a 25 °C)\n→ Quanto MAIS forte o ácido, MAIS FRACA a base conjugada.\n\n**7. pKa — escala prática**\n   pKa = −log Ka\n• pKa < 0 → forte\n• 1–5 → moderadamente fraco\n• > 5 → muito fraco\nEntre dois ácidos: o de **MENOR pKa** é o **MAIS FORTE**.\n\n**8. Grau de ionização (α)**\n   α = [H₃O⁺]equilíbrio / C₀ × 100 %\n• Forte → α ≈ 100%\n• Fraco → α normalmente < 5%\n• α AUMENTA com a diluição (Le Châtelier).\n\n**❌ ERROS FREQUENTES EM EXAME**\n• Aplicar **√(Ka·C)** a ácidos FORTES — em fortes [H₃O⁺] = C directamente. A fórmula da raiz só vale para FRACOS.\n• Achar que **pKa maior = ácido mais forte** → é o CONTRÁRIO. pKa menor → mais forte.\n• No **H₂SO₄**, tratar a 2.ª ionização (HSO₄⁻ → H⁺ + SO₄²⁻) como forte — ela é FRACA (Ka₂ ≈ 1,2 × 10⁻²).\n• Confundir ácido **forte** com ácido **concentrado** (e fraco com diluído) — são propriedades INDEPENDENTES.\n• Esquecer que Ka e Kb dependem APENAS da temperatura — concentração não os altera.\n• Calcular pH de ácido fraco e dar resposta com casas decimais a mais — verifica se a aproximação x << C é válida (regra prática: C/Ka > 1000).`
    },
    'quimica/Soluções tampão e titulações ácido-base': {
        title: 'Soluções tampão e titulações',
        body: `**1. Solução tampão**\nMistura de ÁCIDO FRACO + SUA BASE CONJUGADA (ou base fraca + ácido conjugado).\nResiste a variações de pH quando se adiciona pequena quantidade de ácido ou base.\n\n**Mecanismo**:\n• OH⁻ adicionado → consumido pelo ácido fraco do tampão.\n• H₃O⁺ adicionado → consumido pela base conjugada do tampão.\n\n**2. Equação de Henderson-Hasselbalch**\n   **pH = pKa + log ([A⁻] / [HA])**\n\n• Quando [A⁻] = [HA] → pH = pKa (centro do tampão).\n• Tampão é eficaz para **pH ≈ pKa ± 1**.\n\nEx: tampão acético/acetato (pKa 4,74) com [A⁻]/[HA] = 1 → pH = 4,74.\n\n**3. Titulação ácido-base**\nProcesso para determinar a concentração de uma solução através da reacção com outra de concentração conhecida (titulante).\n\n**Ponto de equivalência**: nº moles ácido = nº moles base.\n\n**pH no ponto de equivalência**:\n• Ácido forte + base forte → pH = 7 (sal neutro).\n• Ácido fraco + base forte → pH > 7 (base conjugada hidrolisa).\n• Ácido forte + base fraca → pH < 7 (ácido conjugado hidrolisa).\n• Ácido fraco + base fraca → depende do par (raro em escola).\n\n**4. Curva de titulação**\nGráfico pH vs volume de titulante. Característica: SALTO ABRUPTO de pH perto do ponto de equivalência.\n• A meia-titulação (V = ½ V_eq), em ácido fraco: pH = pKa.\n\n**5. Indicadores**\nEscolher indicador cuja zona de viragem inclua o pH do ponto de equivalência:\n• Forte+forte (pH=7) → azul de bromotimol (6,0–7,6)\n• Fraco+forte (pH>7) → fenolftaleína (8,3–10,0)\n• Forte+fraco (pH<7) → alaranjado de metilo (3,1–4,4)\n\n**❌ ERROS FREQUENTES EM EXAME**\n• Achar que tampão MANTÉM o pH constante — apenas RESISTE a variações; o pH muda um pouco.\n• Misturar ácido forte + base conjugada de outro ácido e chamar tampão — só funciona com ácido FRACO + sua PRÓPRIA base conjugada.\n• Confundir ponto de equivalência com pH = 7 — só vale para forte+forte.\n• No ponto de equivalência ácido fraco + base forte, dar pH < 7 (é > 7).\n• Escolher indicador errado (fenolftaleína em titulação forte+fraco).\n• Aplicar Henderson-Hasselbalch a soluções que NÃO são tampão.`
    },
    'quimica/Solubilidade e produto de solubilidade (Ks)': {
        title: 'Solubilidade e Ks',
        body: `**1. Equilíbrio de solubilidade**\nPara um sal pouco solúvel AₐBᵦ(s) em equilíbrio com a solução saturada:\n\n   AₐBᵦ(s) ⇌ a A^(n+)(aq) + b B^(m−)(aq)\n\n**2. Produto de solubilidade Ks**\n   **Ks = [A^(n+)]ᵃ · [B^(m−)]ᵇ**\n(o sólido NÃO entra na expressão)\n\nKs depende APENAS da temperatura. Quanto MENOR o Ks, MENOS solúvel o sal.\n\n**3. Solubilidade s** (mol/dm³)\nConcentração máxima do sal dissolvido em água pura, a uma dada T:\n\n• AB (1:1, ex: AgCl): **s = √Ks**\n• AB₂ ou A₂B (1:2): **s = ∛(Ks/4)**\n• A₂B₃ (2:3): s = ⁵√(Ks/108)\n\nEx: AgCl com Ks = 1,8 × 10⁻¹⁰ → s = √Ks ≈ 1,34 × 10⁻⁵ mol/dm³.\nEx: Ag₂CrO₄ com Ks = 1,1 × 10⁻¹² → s = ∛(Ks/4) ≈ 6,5 × 10⁻⁵ mol/dm³.\n(Ag₂CrO₄ tem Ks MENOR mas é MAIS solúvel que AgCl — comparar Ks só vale para sais com a MESMA estequiometria!)\n\n**4. Q vs Ks (prever precipitação)**\n• Q < Ks → solução NÃO saturada (mais sal pode dissolver)\n• Q = Ks → SATURADA (em equilíbrio)\n• Q > Ks → forma-se PRECIPITADO até Q = Ks\n\n**5. Efeito do ião comum**\nAdicionar um ião que JÁ existe no equilíbrio DIMINUI a solubilidade do sal (Le Châtelier).\nEx: AgCl em solução de NaCl 0,1 M → solubilidade do AgCl é muito menor que em água pura.\n\n**6. Efeito do pH**\nSais de ácidos fracos (CaCO₃, Mg(OH)₂, FeS) ficam MAIS solúveis em meio ÁCIDO porque o ião do anião (CO₃²⁻, OH⁻, S²⁻) é consumido por H⁺.\n\n**❌ ERROS FREQUENTES EM EXAME**\n• Comparar Ks de sais com estequiometrias DIFERENTES e concluir solubilidade — só vale comparação directa se forem da mesma forma (1:1 com 1:1, etc.).\n• Esquecer o coeficiente: para A₂B, [A]=2s e Ks=(2s)²·s = 4s³ (NÃO é s³).\n• Achar que Q > Ks significa que o sal vai dissolver — é o CONTRÁRIO (precipita).\n• Aplicar a fórmula s = √Ks a sais que não são 1:1.\n• Esquecer que ião COMUM diminui (não aumenta) a solubilidade.\n• Achar que Ks muda com a concentração inicial — só com T.\n• Incluir o sólido na expressão de Ks.`
    },
    'quimica/Equilíbrio de oxidação-redução': {
        title: 'Oxidação-redução',
        body: `**1. Definições**\n• **Oxidação**: PERDA de electrões → nº de oxidação AUMENTA.\n• **Redução**: GANHO de electrões → nº de oxidação DIMINUI.\n\nMnemónica **OIL RIG**: Oxidation Is Loss, Reduction Is Gain.\n\nNuma reacção redox há SEMPRE oxidação E redução em simultâneo — é uma transferência de electrões.\n\n**2. Agentes**\n• **Agente oxidante**: ACEITA electrões → ele próprio é REDUZIDO.\n• **Agente redutor**: CEDE electrões → ele próprio é OXIDADO.\n\n**3. Números de oxidação — regras**\n1. Elemento puro: 0 (Cu, Fe, O₂, H₂, Cl₂...)\n2. Iões monoatómicos: igual à carga (Na⁺=+1; Cl⁻=−1; Al³⁺=+3)\n3. **O** em compostos: **−2** (excepto: peróxidos H₂O₂ → −1; OF₂ → +2)\n4. **H** em compostos: **+1** (excepto: hidretos metálicos NaH, CaH₂ → −1)\n5. Halogéneos (F, Cl, Br, I) em compostos: −1 (com excepção do Cl/Br/I com O ou F)\n6. Metais alcalinos (Grupo 1): sempre +1\n7. Metais alcalino-terrosos (Grupo 2): sempre +2\n8. Soma de todos os n.o. = carga total da espécie\n   • Composto neutro: soma = 0\n   • Ião poliatómico: soma = carga\n\n**4. Exemplos de cálculo**\n• SO₄²⁻: 4·(−2) + n.o.(S) = −2 → n.o.(S) = +6\n• K₂Cr₂O₇: 2·(+1) + 2·n.o.(Cr) + 7·(−2) = 0 → n.o.(Cr) = +6\n• MnO₄⁻: n.o.(Mn) + 4·(−2) = −1 → n.o.(Mn) = +7\n• NH₃: n.o.(N) + 3·(+1) = 0 → n.o.(N) = −3\n\n**5. Acerto de equações redox**\n• Identificar espécies oxidadas e reduzidas (ver variações de n.o.).\n• Balancear nº de electrões cedidos = electrões ganhos.\n• Ajustar coeficientes para que a transferência total de electrões seja igual.\n\n**❌ ERROS FREQUENTES EM EXAME**\n• Confundir agente oxidante com a espécie OXIDADA — é o CONTRÁRIO. O agente oxidante FAZ outro oxidar; ele próprio é REDUZIDO.\n• Esquecer excepções do O (peróxidos: −1) e do H (hidretos metálicos: −1).\n• Atribuir −2 ao O em OF₂ (é +2 porque F é mais electronegativo).\n• Trocar o sinal: oxidação faz n.o. AUMENTAR (Fe⁰ → Fe²⁺), redução faz DIMINUIR.\n• Achar que apenas há transferência se houver iões — também há em ligações covalentes (n.o. atribuído).\n• Não verificar que a soma dos n.o. iguala a carga total.`
    },
    'quimica/Pilhas e potenciais de eléctrodo': {
        title: 'Pilhas e potencial de eléctrodo',
        body: `**1. Pilha (célula galvânica)**\nDispositivo que converte energia química em energia eléctrica através de uma reacção redox ESPONTÂNEA.\n\n**2. Componentes**\n• **Ânodo (−)**: onde ocorre **OXIDAÇÃO**\n• **Cátodo (+)**: onde ocorre **REDUÇÃO**\n• **Ponte salina** (ou membrana porosa): permite migração de iões para manter a NEUTRALIDADE eléctrica\n• **Circuito externo**: condutor que liga os eléctrodos — é por aqui que os ELECTRÕES viajam (do ânodo para o cátodo)\n\nMnemónica: ânodo = "negaTIVO" e oxidaTION; CáTODO = posiTIVO e reducTION (em pilhas).\n⚠️ Em ELECTRÓLISE é o oposto (ânodo é + e cátodo é −).\n\n**3. fem padrão (E°pilha)**\nUsando potenciais de REDUÇÃO padrão tabelados:\n\n   **E°pilha = E°cátodo − E°ânodo**\n\n• E°pilha > 0 → reacção ESPONTÂNEA (a pilha funciona)\n• E°pilha < 0 → não espontânea (precisa de fonte externa = electrólise)\n• E°pilha = 0 → equilíbrio\n\n**4. Série electroquímica**\nOrdena metais por poder REDUTOR (capacidade de ceder electrões):\n• Metal com E° mais NEGATIVO → mais REDUTOR → oxida-se mais facilmente\n• Metal com E° mais POSITIVO → menos redutor → mais "nobre"\n\nOrdem (do mais redutor para o menos):\nK > Na > Mg > Al > Zn > Fe > Pb > H > Cu > Ag > Au\n\n**5. Pilha de Daniell** (clássica)\nZn(s) | Zn²⁺(aq) ‖ Cu²⁺(aq) | Cu(s)\n• E°(Zn²⁺/Zn) = −0,76 V → ânodo: Zn → Zn²⁺ + 2e⁻\n• E°(Cu²⁺/Cu) = +0,34 V → cátodo: Cu²⁺ + 2e⁻ → Cu\n• E°pilha = +0,34 − (−0,76) = +1,10 V\n\n**6. Aplicações**\n• **Protecção catódica**: usar metal mais redutor (ex: Zn) ligado a Fe → o Zn corrói-se em vez do Fe (ânodo de sacrifício).\n• **Pilhas e baterias** comerciais: alcalina, lítio-ião, chumbo-ácido.\n\n**❌ ERROS FREQUENTES EM EXAME**\n• Trocar ânodo (−) com cátodo (+) — em PILHA, ânodo é o negativo e o cátodo é o positivo.\n• Em ELECTRÓLISE inverter sem perceber — aí é o contrário.\n• Aplicar E°pilha = E°ânodo − E°cátodo (sinal trocado) — é cátodo MENOS ânodo.\n• Inverter o sinal de E° quando a equação é escrita ao contrário — usar SEMPRE E° de redução tabelado, e fazer "cátodo − ânodo".\n• Achar que electrões viajam pelo electrólito — viajam pelo CIRCUITO EXTERNO. Pelo electrólito viajam os IÕES.\n• Esquecer que metal mais redutor (E° mais negativo) é o que se OXIDA na pilha.\n• Confundir poder redutor com poder oxidante (são opostos).\n• Multiplicar E° pelos coeficientes estequiométricos — E° NÃO depende dos coeficientes.`
    }
};

// Reservado — exercícios complexos vivem em content_11_q_extra.js (lazy load)
const EXERCISES_11 = [];

const YEARS_AVAILABLE = [
    { year: 2,  label: '2.º ano',  cycle: '1.º ciclo' },
    { year: 5,  label: '5.º ano',  cycle: '2.º ciclo' },
    { year: 6,  label: '6.º ano',  cycle: '2.º ciclo' },
    { year: 11, label: '11.º ano', cycle: 'Secundário' }
];

const SUBJECTS_BY_YEAR   = { 2: SUBJECTS_2,   5: SUBJECTS_5,   6: SUBJECTS_6,   11: SUBJECTS_11 };
const CURRICULUM_BY_YEAR = { 2: CURRICULUM_2, 5: CURRICULUM_5, 6: CURRICULUM_6, 11: CURRICULUM_11 };
const EXERCISES_BY_YEAR  = { 2: EXERCISES_2,  5: EXERCISES_5,  6: EXERCISES_6,  11: EXERCISES_11 };
const LESSONS_BY_YEAR    = { 2: LESSONS_2,    5: LESSONS_5,    6: LESSONS_6,    11: LESSONS_11 };
const PERIODS_BY_YEAR    = { 2: PERIODS_2,    5: PERIODS_5,    6: PERIODS_6,    11: PERIODS_11 };

// Mutáveis: app.js usa SUBJECTS, CURRICULUM, EXERCISES, LESSONS, PERIODS
// directamente. setActiveYear() troca-os atomicamente quando se muda de perfil.
// Iniciam vazios — só são preenchidos quando existe um perfil activo (regra: nada é
// carregado por defeito; só os anos dos perfis criados é que ficam disponíveis).
let SUBJECTS   = {};
let CURRICULUM = {};
let EXERCISES  = {};
let LESSONS    = {};
let PERIODS    = [];

function setActiveYear(year) {
    if (!SUBJECTS_BY_YEAR[year]) {
        SUBJECTS = {}; CURRICULUM = {}; EXERCISES = {}; LESSONS = {}; PERIODS = [];
        window.SUBJECTS = SUBJECTS; window.CURRICULUM = CURRICULUM;
        window.EXERCISES = EXERCISES; window.LESSONS = LESSONS; window.PERIODS = PERIODS;
        window.activeYear = null;
        return;
    }
    SUBJECTS   = SUBJECTS_BY_YEAR[year];
    CURRICULUM = CURRICULUM_BY_YEAR[year];
    EXERCISES  = EXERCISES_BY_YEAR[year];
    LESSONS    = LESSONS_BY_YEAR[year];
    PERIODS    = PERIODS_BY_YEAR[year];
    window.SUBJECTS   = SUBJECTS;
    window.CURRICULUM = CURRICULUM;
    window.EXERCISES  = EXERCISES;
    window.LESSONS    = LESSONS;
    window.PERIODS    = PERIODS;
    window.activeYear = year;
}

window.YEARS_AVAILABLE     = YEARS_AVAILABLE;
window.SUBJECTS_BY_YEAR    = SUBJECTS_BY_YEAR;
window.CURRICULUM_BY_YEAR  = CURRICULUM_BY_YEAR;
window.EXERCISES_BY_YEAR   = EXERCISES_BY_YEAR;
window.LESSONS_BY_YEAR     = LESSONS_BY_YEAR;
window.PERIODS_BY_YEAR     = PERIODS_BY_YEAR;
window.setActiveYear       = setActiveYear;
window.SUBJECTS   = SUBJECTS;
window.CURRICULUM = CURRICULUM;
window.EXERCISES  = EXERCISES;
window.LESSONS    = LESSONS;
window.PERIODS    = PERIODS;
window.activeYear = null;
